const b = $input.first().json.body || {};
const name = String(b.name || '').trim(), email = String(b.email || '').trim().toLowerCase();
const msg = String(b.message || ''), company = String(b.company || '').trim();
const budget = Number(String(b.budget || '0').replace(/[^0-9.]/g, '')) || 0;
const txt = (msg + ' ' + (b.service || '')).toLowerCase();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) throw new Error('Invalid or missing email');
const spam = /(backlinks|seo ranking|crypto|casino|guaranteed traffic|viagra)/.test(txt);
let score = 0; const why = [];
if (budget >= 2000) { score += 2; why.push('budget>=2000'); } else if (budget >= 500) { score += 1; why.push('budget>=500'); }
if (/(urgent|asap|urgente|this week|esta semana|hoje)/.test(txt)) { score += 1; why.push('urgent'); }
if (/(quote|pricing|price|orçamento|orcamento|proposal|proposta|contratar|hire)/.test(txt)) { score += 1; why.push('buying intent'); }
if (company) { score += 1; why.push('company given'); }
const priority = spam ? 'spam' : score >= 3 ? 'hot' : score >= 1 ? 'warm' : 'cold';
const pt = /(olá|ola|preciso|gostaria|orçamento|orcamento|quero|bom dia|boa tarde|proposta)/.test(txt) || b.lang === 'pt';
const first = name.split(' ')[0] || (pt ? 'tudo bem' : 'there');
const sla = priority === 'hot' ? (pt ? 'em até 2 horas' : 'within 2 hours') : (pt ? 'em até 1 dia útil' : 'within 1 business day');
const reply = priority === 'spam' ? '' : pt ? `Olá, ${first}! Recebemos sua mensagem e respondemos ${sla}.` : `Hi ${first}, thanks for reaching out. We will reply ${sla}.`;
return [{json: {received_at: new Date().toISOString(), name, email, company, budget, service: b.service || '', message: msg, score, priority, why: why.join('; '), lang: pt ? 'pt' : 'en', reply}}];

const q = v => '"' + String(v ?? '').replace(/"/g, '""').replace(/[\r\n]+/g, ' ') + '"';

const j = $input.first().json;
const line = ['received_at','name','email','company','budget','service','priority','score','why','message'].map(k => q(j[k])).join(',') + '\n';
const bin = await this.helpers.prepareBinaryData(Buffer.from(line, 'utf8'), 'leads.csv', 'text/plain');
return [{json: j, binary: {data: bin}}];
